package network
import("context";"errors";"net";"testing")
func TestNoFalseInternetClaim(t *testing.T){list:=func()([]net.Interface,error){return []net.Interface{{Index:2,Name:"Ethernet",Flags:net.FlagUp},{Index:1,Name:"lo",Flags:net.FlagUp|net.FlagLoopback}},nil};addresses:=func(net.Interface)([]net.Addr,error){return []net.Addr{&net.IPNet{IP:net.ParseIP("169.254.1.2"),Mask:net.CIDRMask(16,32)}},nil};s,err:=inspect(context.Background(),list,addresses);if err!=nil||s.Internet!="not_tested"||!s.HasActiveAdapter||s.Interfaces[0].Index!=1{t.Fatalf("%+v %v",s,err)}}
func TestCancellationAndFailures(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());cancel();if _,err:=Inspect(ctx);!errors.Is(err,context.Canceled){t.Fatal(err)};list:=func()([]net.Interface,error){return []net.Interface{{Name:"test"}},nil};s,err:=inspect(context.Background(),list,func(net.Interface)([]net.Addr,error){return nil,errors.New("unavailable")});if err!=nil||!s.Interfaces[0].AddressesUnavailable||s.Internet!="not_tested"{t.Fatal(s,err)};_,err=inspect(context.Background(),func()([]net.Interface,error){return nil,errors.New("failed")},nil);if err==nil{t.Fatal("missing enumeration error")}}
